"""Final wall-time/ownership handoff; this command never schedules model work."""
import subprocess
from zoneinfo import ZoneInfo
from .report_helpers import *

def main():
 session=read(HERE/'SESSION.json');resource=read(HERE/'tables/RESOURCES.json');operational=read(HERE/'reports/LATEST_OPERATIONAL_STATE.json');resumed=read(HERE/'reports/CORE_RESUMPTION.json');checks=read(HERE/'reports/FINAL_VERIFICATION.json')
 end=datetime.now(timezone.utc);start=datetime.fromisoformat(session['start_utc']);deadline=datetime.fromisoformat(session['deadline_utc']);assert end<deadline
 current=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip();zone=ZoneInfo('America/New_York');hours=(end-start).total_seconds()/3600
 cutoff=read(HERE/'inputs/CORE_CUTOFF.json');before={r['job']['id'] for r in cutoff['jobs'] if r['eligible']};later=[]
 for r in cutoff['jobs']:
  name=r['job']['id'];p=ROOT/'artifacts/runs'/name/'status.json'
  if name not in before and p.exists():
   d=read(p)
   if d['status']=='completed':later.append({'run_id':name,'status':'completed after analysis cutoff','status_sha256':sha(p),'main_tables_unchanged':True})
 write(HERE/'reports/OPERATIONAL_AFTER_CUTOFF.json',{'utc':end.isoformat(),'later_completed':later,'analysis_population_unchanged':True})
 starting=read(HERE/'reports/STARTING_INVENTORY.json')
 recorded=operational['global_reserved_seconds'];active=operational['active_upper_unrecorded_seconds'];remaining=operational['forecast']['conservative_remaining_core_hours'];window_extra=resource.get('conservative_additional_unledgered_window_seconds',0)
 reserve_total=(recorded+active+window_extra)/3600+remaining+2+.5
 report={'start_utc':start.isoformat(),'end_utc':end.isoformat(),'elapsed_hours':hours,'deadline_utc':deadline.isoformat(),'start_America_New_York':start.astimezone(zone).isoformat(),'end_America_New_York':end.astimezone(zone).isoformat(),'input_commit':session['input_commit'],'current_commit_before_handoff_document':current,'evidence_cutoff_utc':cutoff['cutoff_utc'],'resource_summary':resource['totals'],'starting_recorded_project_hours':starting['recorded_reserved_hours'],'starting_reconciled_project_hours':starting['reconciled_reserved_hours'],'recorded_project_hours':recorded/3600,'conservative_project_hours_with_active_tail_and_full_handoff_window':(recorded+active+window_extra)/3600,'remaining_core_conservative_hours':remaining,'review_obligation_hours_reserved':2,'contingency_hours':.5,'conservative_total_with_obligations_hours':reserve_total,'native_owner_pid':resumed['native_owner_pid'],'human_annotations':0,'no_new_waiter':True,'core_continues':True,'later_core_completions_excluded_from_locked_tables':later,'verification':checks}
 assert reserve_total<=96;write(HERE/'reports/FINAL_SESSION.json',report)
 lines=['# Session handoff\n',f"Started **{start.isoformat()} UTC** ({start.astimezone(zone).strftime('%Y-%m-%d %H:%M:%S %Z')}, America/New_York). Finished **{end.isoformat()} UTC** ({end.astimezone(zone).strftime('%Y-%m-%d %H:%M:%S %Z')}). Actual elapsed time: **{hours:.3f} hours**. Absolute deadline: {deadline.isoformat()}; the final hour of that ceiling was reserved for verification. Work finishes early because the feasible frozen evaluation and author-review manuscript are complete; it does not wait for the separate core campaign.\n",f"Input commit: `{session['input_commit']}`. Current package commit before this final handoff document: `{current}`. The final local commit is reported in the chat handoff and can be obtained with `git log -1 -- supplements/automated_evaluation_008`. Branch main; nothing pushed.\n",'## Completed evidence and verification\n','Both judges completed the fixed 692-task main list, the 108 stability-probe tasks, and 32 controlled-event judgments. The main list includes 80 held-out controls, 72 fixed events and 540 broader opportunities. All 64 controlled conversations and 2,816 actor/answerer calls completed. One Qwen time-limit failure retained 640 main tasks; a separately frozen continuation completed only the remaining 52 IDs. Thirty-two generated but unwritten outputs from the failed batch are unavailable, with their full cost retained. No record was retried because its label was unfavorable or invalid. The initial missing-dependency failure occurred before model calls and was also retained.\n','The consolidated paper uses 37 eligible main evaluation cells at the fixed 181-stage cutoff. Original exclusions and unfavorable comparisons remain. Later operational completions below are not silently added. Historical freezes and forms pass verification. No independent human semantic annotations were collected.\n',markdown_table(['Check','Status'],[[k,str(v)] for k,v in checks.items() if k not in ['commands','hashes','details']]),'Code/quote/package checks are not semantic validation. Judge failures, missingness, conditional extraction, and shared errors remain scientific limitations.\n','## Resources\n',f"At startup, recorded project use was {starting['recorded_reserved_hours']:.6f} hours ({starting['reconciled_reserved_hours']:.6f} with the active tail reconciled). Core work continuing during this session is counted separately from the new stage. Stage008 native RunLedger reservations: **{resource['stage_hours']:.6f} GPU-hours**, {resource['totals']['model_calls']:,} calls, {resource['totals']['input_tokens']:,} input tokens and {resource['totals']['output_tokens']:,} output tokens. Compatibility rollout: **{resource['compatibility_hours']:.6f} hours**; controlled-event judging is separately included in the stage total. Peak observed device allocation: {resource['peak_vram_bytes']/1024**3:.3f} GiB, including vLLM KV reservation.\n",f"The more conservative full exclusive handoff window, from the previous core fit ending to native-owner resumption, is **{resource.get('exclusive_handoff_window_hours',0):.6f} hours**, also below the four-hour cap. It includes dispatch, mirroring and CPU gaps; it is not billed pod uptime. Recorded project consumption at the operational snapshot is **{recorded/3600:.6f}/96 hours**. Adding the active heartbeat tail, the extra full-handoff margin, **{remaining:.3f} hours** conservative remaining core work, **2 hours** review obligation and **0.5 hour** contingency gives **{reserve_total:.3f}/96 hours**. Already consumed stage work is not counted again. No actual dollar rate or billed pod-start record is available.\n",f"Local free bytes: {operational['local_free_bytes']:,}; remote free bytes at the latest read-only check: {operational.get('remote',{}).get('free_bytes','not sampled')}. No model weights or original artifacts were deleted by this stage. Native lossless storage policy remains under its original owner.\n",'## Current ownership and exact recovery path\n',f"The original controller was resumed with its recorded command and connection environment: PID **{resumed['native_owner_pid']}**. The completed stage-boundary hold is archived at `artifacts/automated_evaluation_008/completed_boundary_hold.json`. Its original private command/environment is preserved mode0600 at `artifacts/automated_evaluation_008/original_owner_private.json`; it is deliberately not committed or printed. Resumption proof: `reports/CORE_RESUMPTION.json`. The original review coordinator remains its owner; intent002 stays disabled. No new indefinite waiter or duplicate GPU worker remains.\n",f"Latest operational core state: `{json.dumps(operational['core_state'],ensure_ascii=False)}`. Review status: `{operational['review_state'].get('status')}`. Completed core stages at this operational snapshot: {operational['core_completed']}/241. The next stage immediately after the handoff was `main-qwen-c6-43-eval`; native queue order is unchanged.\n",'Monitor read-only from `dualingCharacters/`:\n\n```bash\nPYTHONPATH=src:. .venv/bin/python -m supplements.automated_evaluation_008.operations --remote\n```\n\nUse `artifacts/campaign_state.json`, `artifacts/campaign_configs/<run_id>.log`, `artifacts/run_registry.jsonl`, and `artifacts/automated_evaluation_008/core_resume.log`. If an infrastructure failure occurs, first verify the original owner and GPU worker are absent, preserve partial artifacts and costs, and use the existing audited `artifacts/campaign_resume.json` mechanism. With the established PCC connection environment, the native command is `PYTHONPATH=src .venv/bin/python -m pcc.campaign`. Do not start it beside a healthy owner, rerun completed evaluations, or reuse the one-time008resumption script after its hold has been archived.\n','## Delivered package and author decisions\n','[FINAL_RESULTS.md](FINAL_RESULTS.md), [JUDGE_CALIBRATION.md](JUDGE_CALIBRATION.md), [anonymous paper](paper/manuscript.pdf), [identified project copy](paper/author_review.pdf), [evidence index](EVIDENCE_INDEX.md), [reproduction commands](REPRODUCE.md), [claims](CLAIM_TO_EVIDENCE.csv), and [AI assistance/author responsibility](AI_ASSISTANCE_AND_AUTHOR_REVIEW.md). The committed evidence bundle supports offline numerical and selected-dialogue reproduction.\n','The author must decide the final scientific scope and interpretations, supply authorship/anonymity information, and critically review/edit the disclosure and manuscript for conference compliance. Human rater recruitment is not required. The bounded characterization is ready for author review; the original full learning/transfer study remains incomplete at its cutoff, and no guarantee of acceptance or direct-submission compliance is made.\n']
 (HERE/'SESSION_REPORT.md').write_text('\n'.join(lines));print({'elapsed_hours':hours,'core_owner':resumed['native_owner_pid'],'project_conservative_hours':reserve_total})
if __name__=='__main__':main()
